def update(stock, changes):
    """Apply ordered stock changes without mutating either input."""
    original = dict(stock)
    updated = dict(stock)

    for key, delta in changes:
        if key not in updated or updated[key] + delta < 0:
            return {"ok": False, "stock": original}
        updated[key] += delta

    return {"ok": True, "stock": updated}

import unittest

from app import update


class UpdateTests(unittest.TestCase):
    def test_applies_changes_in_order(self):
        stock = {"apple": 3, "pear": 1}
        changes = [["apple", -2], ["pear", 4], ["apple", 1]]
        self.assertEqual(update(stock, changes), {"ok": True, "stock": {"apple": 2, "pear": 5}})

    def test_rejects_negative_intermediate_even_if_later_change_recovers(self):
        stock = {"apple": 2}
        changes = [["apple", -3], ["apple", 5]]
        self.assertEqual(update(stock, changes), {"ok": False, "stock": {"apple": 2}})

    def test_failure_after_valid_changes_returns_original_stock(self):
        stock = {"apple": 5, "pear": 2}
        changes = [["apple", -2], ["pear", -3]]
        self.assertEqual(
            update(stock, changes),
            {"ok": False, "stock": {"apple": 5, "pear": 2}},
        )

    def test_rejects_absent_key_and_returns_original_stock(self):
        stock = {"apple": 5}
        changes = [["orange", 1]]
        self.assertEqual(update(stock, changes), {"ok": False, "stock": {"apple": 5}})

    def test_does_not_mutate_inputs_on_success(self):
        stock = {"apple": 5}
        changes = [["apple", -2]]
        original_stock = dict(stock)
        original_changes = [change[:] for change in changes]
        result = update(stock, changes)
        self.assertEqual(stock, original_stock)
        self.assertEqual(changes, original_changes)
        self.assertIsNot(result["stock"], stock)

    def test_does_not_mutate_inputs_on_failure(self):
        stock = {"apple": 1}
        changes = [["apple", 2], ["apple", -4]]
        original_stock = dict(stock)
        original_changes = [change[:] for change in changes]
        result = update(stock, changes)
        self.assertEqual(stock, original_stock)
        self.assertEqual(changes, original_changes)
        self.assertIsNot(result["stock"], stock)

    def test_allows_value_to_reach_zero(self):
        self.assertEqual(
            update({"apple": 2}, [["apple", -2]]),
            {"ok": True, "stock": {"apple": 0}},
        )

    def test_empty_changes_returns_equal_copy(self):
        stock = {"apple": 2}
        result = update(stock, [])
        self.assertEqual(result, {"ok": True, "stock": stock})
        self.assertIsNot(result["stock"], stock)


if __name__ == "__main__":
    unittest.main()

