import unittest

from app import update


class UpdateTests(unittest.TestCase):
    def test_applies_changes_in_order_to_a_copy(self):
        stock = {"apples": 5, "pears": 2}
        changes = [["apples", -2], ["apples", 4], ["pears", 1]]

        result = update(stock, changes)

        self.assertEqual(
            result,
            {"ok": True, "stock": {"apples": 7, "pears": 3}},
        )
        self.assertIsNot(result["stock"], stock)

    def test_negative_intermediate_value_returns_original_stock(self):
        stock = {"apples": 5, "pears": 2}
        changes = [["apples", 3], ["pears", -3], ["pears", 10]]

        result = update(stock, changes)

        self.assertEqual(
            result,
            {"ok": False, "stock": {"apples": 5, "pears": 2}},
        )
        self.assertIsNot(result["stock"], stock)

    def test_absent_key_returns_original_stock(self):
        stock = {"apples": 5}
        changes = [["apples", 2], ["pears", 1]]

        result = update(stock, changes)

        self.assertEqual(result, {"ok": False, "stock": {"apples": 5}})
        self.assertIsNot(result["stock"], stock)

    def test_success_does_not_mutate_inputs(self):
        stock = {"apples": 5}
        changes = [["apples", -2]]
        original_stock = {"apples": 5}
        original_changes = [["apples", -2]]

        update(stock, changes)

        self.assertEqual(stock, original_stock)
        self.assertEqual(changes, original_changes)

    def test_failure_does_not_mutate_inputs(self):
        stock = {"apples": 5}
        changes = [["apples", 2], ["missing", 1]]
        original_stock = {"apples": 5}
        original_changes = [["apples", 2], ["missing", 1]]

        update(stock, changes)

        self.assertEqual(stock, original_stock)
        self.assertEqual(changes, original_changes)


if __name__ == "__main__":
    unittest.main()
